CREATE TRIGGER intentions_tombstone_after_delete
AFTER DELETE ON intentions
WHEN EXISTS (
  SELECT 1 FROM action_path_items WHERE intention_id = old.id
)
BEGIN
  INSERT INTO deleted_intentions (intention_id, title)
  VALUES (old.id, old.title);
END;

CREATE TRIGGER intentions_fts_after_insert
AFTER INSERT ON intentions
BEGIN
  INSERT INTO intention_titles_fts(rowid, title_search_key)
  VALUES (new.rowid, new.title_search_key);
END;

CREATE TRIGGER intentions_fts_after_update_search_content
AFTER UPDATE OF title ON intentions
BEGIN
  INSERT INTO intention_titles_fts(
    intention_titles_fts, rowid, title_search_key
  ) VALUES ('delete', old.rowid, old.title_search_key);
  INSERT INTO intention_titles_fts(rowid, title_search_key)
  VALUES (new.rowid, new.title_search_key);
END;

CREATE TRIGGER intentions_fts_after_delete
AFTER DELETE ON intentions
BEGIN
  INSERT INTO intention_titles_fts(
    intention_titles_fts, rowid, title_search_key
  ) VALUES ('delete', old.rowid, old.title_search_key);
END;

